class Solution {
public:
    int distinctSequences(int n) {
        const int MOD = 1e9 + 7;
        if (n == 1) return 6;
        bool cop[6][6];
        for (int i = 0; i < 6; i++) for (int j = 0; j < 6; j++) cop[i][j] = __gcd(i + 1, j + 1) == 1;
        vector<vector<long long>> dp(6, vector<long long>(6, 1));
        for (int step = 1; step < n; step++) {
            vector<vector<long long>> ndp(6, vector<long long>(6, 0));
            for (int a = 0; a < 6; a++)
                for (int b = 0; b < 6; b++) {
                    if (!dp[a][b]) continue;
                    for (int c = 0; c < 6; c++)
                        if (cop[a][c] && c != a && c != b)
                            ndp[c][a] = (ndp[c][a] + dp[a][b]) % MOD;
                }
            dp = move(ndp);
        }
        long long ans = 0;
        for (auto& r : dp) for (long long v : r) ans = (ans + v) % MOD;
        return (int)ans;
    }
};

