class Solution {
    public int distinctSequences(int n) {
        final int MOD = 1_000_000_007;
        if (n == 1) return 6;
        boolean[][] cop = new boolean[6][6];
        for (int i = 0; i < 6; i++) for (int j = 0; j < 6; j++) cop[i][j] = gcd(i + 1, j + 1) == 1;
        long[][] dp = new long[6][6];
        for (long[] r : dp) java.util.Arrays.fill(r, 1);
        for (int step = 1; step < n; step++) {
            long[][] ndp = new long[6][6];
            for (int a = 0; a < 6; a++)
                for (int b = 0; b < 6; b++) {
                    if (dp[a][b] == 0) continue;
                    for (int c = 0; c < 6; c++)
                        if (cop[a][c] && c != a && c != b)
                            ndp[c][a] = (ndp[c][a] + dp[a][b]) % MOD;
                }
            dp = ndp;
        }
        long ans = 0;
        for (long[] r : dp) for (long v : r) ans = (ans + v) % MOD;
        return (int) ans;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
