class Solution:
    def distinctSequences(self, n: int) -> int:
        MOD = 10**9 + 7
        if n == 1: return 6
        from math import gcd
        idx = lambda a, b: a * 6 + b
        M = [[0] * 36 for _ in range(36)]
        for a in range(6):
            for b in range(6):
                for c in range(6):
                    if gcd(a + 1, c + 1) == 1 and c != a and c != b:
                        M[idx(c, a)][idx(a, b)] = 1
        def mul(A, B):
            C = [[0] * 36 for _ in range(36)]
            for i in range(36):
                Ai = A[i]
                for k in range(36):
                    if Ai[k]:
                        Bk = B[k]
                        for j in range(36):
                            C[i][j] = (C[i][j] + Ai[k] * Bk[j]) % MOD
            return C
        R = [[1 if i == j else 0 for j in range(36)] for i in range(36)]
        e = n - 1
        while e:
            if e & 1: R = mul(R, M)
            M = mul(M, M); e >>= 1
        v = [1] * 36
        ans = 0
        for i in range(36):
            ans = (ans + sum(R[i][j] * v[j] for j in range(36))) % MOD
        return ans

