// Matrix power variant: build 36x36 transition matrix, exponentiate by
// squaring. Same construction as the Python version; O(36^3 log n).
class Solution {
public:
    int distinctSequences(int n) {
        const long long MOD = 1e9 + 7;
        if (n == 1) return 6;
        vector<vector<long long>> M(36, vector<long long>(36, 0));
        for (int a = 0; a < 6; a++) for (int b = 0; b < 6; b++) for (int c = 0; c < 6; c++)
            if (__gcd(a + 1, c + 1) == 1 && c != a && c != b) M[c * 6 + a][a * 6 + b] = 1;
        auto mul = [&](vector<vector<long long>> A, vector<vector<long long>> B) {
            vector<vector<long long>> C(36, vector<long long>(36, 0));
            for (int i = 0; i < 36; i++) for (int k = 0; k < 36; k++) if (A[i][k])
                for (int j = 0; j < 36; j++) C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            return C;
        };
        vector<vector<long long>> R(36, vector<long long>(36, 0));
        for (int i = 0; i < 36; i++) R[i][i] = 1;
        long long e = n - 1;
        while (e) { if (e & 1) R = mul(R, M); M = mul(M, M); e >>= 1; }
        long long ans = 0;
        for (int i = 0; i < 36; i++) for (int j = 0; j < 36; j++) ans = (ans + R[i][j]) % MOD;
        return (int)ans;
    }
};

