// Matrix exponentiation variant over the 36 pair-states; construction
// mirrors the C++ version. O(36^3 log n).
class Solution {
    public int distinctSequences(int n) {
        final long MOD = 1_000_000_007L;
        if (n == 1) return 6;
        long[][] M = new long[36][36];
        for (int a = 0; a < 6; a++) for (int b = 0; b < 6; b++) for (int c = 0; c < 6; c++)
            if (gcd(a + 1, c + 1) == 1 && c != a && c != b) M[c * 6 + a][a * 6 + b] = 1;
        long[][] R = new long[36][36];
        for (int i = 0; i < 36; i++) R[i][i] = 1;
        long e = n - 1;
        while (e > 0) {
            if ((e & 1) == 1) R = mul(R, M, MOD);
            M = mul(M, M, MOD); e >>= 1;
        }
        long ans = 0;
        for (long[] r : R) for (long v : r) ans = (ans + v) % MOD;
        return (int) ans;
    }
    private long[][] mul(long[][] A, long[][] B, long MOD) {
        long[][] C = new long[36][36];
        for (int i = 0; i < 36; i++) for (int k = 0; k < 36; k++) if (A[i][k] != 0)
            for (int j = 0; j < 36; j++) C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
        return C;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

