var distinctSequences = function(n) {
    const MOD = 1e9 + 7;
    if (n === 1) return 6;
    const g = (a, b) => b ? g(b, a % b) : a;
    const M = Array.from({length: 36}, () => new Array(36).fill(0));
    for (let a = 0; a < 6; a++) for (let b = 0; b < 6; b++) for (let c = 0; c < 6; c++)
        if (g(a + 1, c + 1) === 1 && c !== a && c !== b) M[c * 6 + a][a * 6 + b] = 1;
    const mul = (A, B) => {
        const C = Array.from({length: 36}, () => new Array(36).fill(0));
        for (let i = 0; i < 36; i++) for (let k = 0; k < 36; k++) if (A[i][k])
            for (let j = 0; j < 36; j++) C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
        return C;
    };
    let R = Array.from({length: 36}, (_, i) => Array.from({length: 36}, (_, j) => i === j ? 1 : 0));
    let e = n - 1;
    while (e > 0) { if (e & 1) R = mul(R, M); M = mul(M, M); e >>= 1; }
    let ans = 0;
    for (const r of R) for (const v of r) ans = (ans + v) % MOD;
    return ans;
};
